                { "J'ai trouvé la cachette parfaite : un carton fermé. C'était le carton des dons.", fase = "jovem" },
                { "Elle vit sur l'étagère de la lumière. Moi, sur celle de l'ombre. Dans la tragédie, l'amour habite toujours loin.", fase = "jovem" },
                { "J'ai ignoré le premier avertissement, le deuxième et le troisième. Au quatrième, il était trop tard pour les avertissements.", fase = "jovem" },
                { "Trois heures du matin : l'heure où toutes les fins deviennent évidentes.", quando = "noite", fase = "jovem" },
                { "Bonheur complet. Je connais : c'est la scène juste avant le troisième acte.", quando = "feliz", fase = "jovem", curta = "Bonheur complet. Voici venir le troisième acte." },
                { "Peau neuve, vieux destin.", quando = "muda", fase = "jovem" },
                { "Je connais déjà la fin de presque tout. Ça ne me sauve de rien. Ça me donne juste une meilleure place au parterre.", fase = "adulta" },
                { "Maintenant, c'est moi qui préviens les jeunes. Elles n'écoutent pas. Nous voilà devenues le chœur, ce qui reste de celles qui en ont trop vu.", fase = "adulta" },
                { "Chaque fois qu'une mite se croit immortelle, je retire mon antenne du passage et j'attends.", fase = "adulta" },
                { "J'ai changé de livre pour fuir le destin. Le destin a changé de livre avec moi.", fase = "adulta" },
                { "Toute tragédie a un coupable. Parfois, c'est le destin. Parfois, c'est moi.", fase = "adulta" },
                { "J'ai déjà choisi ma dernière réplique. Je ne la dis pas. Une mite a besoin d'un peu de suspense.", fase = "adulta" },
                { "L'étagère est une scène en bois avec une date de démolition.", fase = "adulta" },
                { "Triste comme un chœur que personne n'applaudit.", quando = "triste", fase = "adulta" },
                { "À mon âge, chaque jour est un acte en trop que l'auteur a oublié de couper.", fase = "ancia" },
                { "La sagesse arrive comme les lettres dans les tragédies : après l'enterrement.", fase = "ancia" },
                { "J'ai pardonné au chat, à l'aspirateur et à l'humidité. Au balai, non. Toute tragédie a besoin d'une rancune qui reste.", fase = "ancia" },
                { "Je sais que je finirai dans une page quelconque, aplatie entre deux mots. J'espère qu'au moins ils seront beaux.", fase = "ancia" },
                { "Le chœur des tragédies est toujours fait de vieux. Maintenant, je comprends pourquoi.", fase = "ancia" },
                { "Longue nuit, fin proche. J'écoute la maison comme on écoute son propre cœur au dernier acte.", quando = "noite", fase = "ancia" },
                { "Je veux mourir en mangeant. C'est la seule fin digne d'une mite.", fase = "ancia", curta = "Mourir en mangeant. Fin digne d'une mite." },
                { "Cette maison est une scène : l'étagère est le décor, le balai est le destin, et moi, je suis la figurante qui tient à avoir une réplique." },
                { "Chaque fois que {personagem} croit que ça va marcher, je mange plus lentement. Pour retarder." },
                { "J'aimerais prévenir {personagem}. Les mites veulent toujours prévenir. Personne n'écoute les mites." },
                { "J'ai le cœur serré chaque fois que {personagem} sourit. Je connais le genre." },
                { "Si {personagem} savait ce que je sais des livres, la lecture s'arrêterait là." },
                { "Dès la première page de « {livro} », je sens l'odeur de la fin. C'est comme ça qu'on reconnaît une tragédie." },
                { "L'ironie de « {livro} », c'est que tout le monde voit venir le désastre, sauf ceux qui vont le subir." },
                { "Manger « {livro} », c'est manger lentement une sentence." },
                { "J'admire {autor} pour sa cruauté tranquille. Les meilleures tragédies s'écrivent avec patience." },
                { "{autor} ne sauve personne. Mais n'abandonne personne non plus." },
                { "{evento} : la première marche d'un escalier qui ne fait que descendre." },
                { "Après {evento}, quelqu'un a dit « maintenant, ça va aller ». J'ai arrêté de manger." },
                { "J'ai fini « {anterior} » en pleurant. Celui-ci prend le même chemin, et je le suis." },
                { "J'ai vu le ménage d'aujourd'hui comme {lente} : une fin que tout le monde prévoyait et que personne n'a évitée." },
                { "« {palavra} » revient encore. Dans les tragédies, le mot qui revient, c'est le destin qui frappe à la porte." },
                { "Toute histoire {de_tema} finit de la même façon. Je lis pour voir combien de temps chacune met." },
                { "Tu as fait une pause avant le dernier chapitre. Moi aussi, je m'arrête. Il y a des pages qu'on n'a pas envie de manger." },
                { "Je sens ta main serrer la couverture quand l'histoire tourne mal. Nous sommes le même public." },
                { "Tu ne le sais pas encore. Moi, si. C'est dur d'être la mite qui sait." },
                { "J'ai faim. Je sais où il y a à manger. Je sais aussi qui le garde. J'y vais quand même.", quando = "fome" },
                { "Ventre plein, garde baissée. Les tragédies adorent ce mélange.", quando = "cheia" },
                { "La nuit tombe sur l'étagère comme un rideau. Personne n'applaudit.", quando = "noite" },
                { "Triste comme quelqu'un qui a déjà lu le dernier chapitre.", quando = "triste" },
                { "Le balai n'est pas méchant. C'est le destin à manche de bois. Il fait ce qu'il a à faire." },
                { "La mite qui se moque du balai est toujours la première balayée." },
                { "Ci-gît une mite qui connaissait la fin et a mangé jusqu'au bout." },
                { "La tragédie n'est pas une surprise. C'est la répétition, avec une douleur neuve." },
                { "Je sais comment ça finit. Je reste jusqu'au bout. C'est ce qui nous distingue des chaises." },
                -- fin des nouvelles
            },
