                { "J'ai voulu syndiquer les mites du garage. Ordre du jour : l'humidité, la nourriture et le droit d'exister sans spray. Personne n'est venu. Elles travaillaient toutes.", fase = "jovem" },
                { "Ce livre parle beaucoup {de_tema}. Moi, j'aimerais savoir qui a payé le papier, qui a porté les cartons et qui a nettoyé après.", fase = "adulta" },
