                -- nouvelles (brouillons du 29/10/2026, cartoes/rascunhos/influencias)
                { "Je suis née dans le carton du garage, entre les vieux journaux et la gouttière. Les mites de la vitrine sont nées dans un autre monde.", fase = "ninfa" },
