                { "Ma mère a élevé trente filles dans un carton de journaux. Personne n'a écrit là-dessus.", fase = "ninfa" },
                { "À peine sortie de l'œuf, je suis allée chercher à manger. Il n'y a pas d'enfance dans le carton du garage.", fase = "ninfa" },
