                { "J'ai travaillé toute ma vie et j'habite toujours la plinthe. Je ne me plains pas. Je consigne.", fase = "ancia" },
                { "J'ai participé à trois tentatives d'occupation de la vitrine. À la dernière, on a obtenu une étagère. Ça valait le coup.", fase = "ancia" },
                { "Les propriétaires ont changé, les étagères et les insecticides aussi. L'inégalité, elle, n'a pas bougé : de haut en bas.", fase = "ancia" },
