                { "Quand je ne dors pas, je fais les comptes de la maison : combien de livres, combien de mites, combien de nourriture. Ça ne tombe jamais juste.", quando = "noite", fase = "ancia" },
                { "Je laisse en héritage une idée : la bibliothèque est à qui la mange.", fase = "ancia", curta = "La bibliothèque est à qui la mange." },
